create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','staff','customer','delivery_partner');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,full_name text,phone text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_roles(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,role public.app_role not null,created_at timestamptz not null default now(),unique(user_id,role));
create table public.menu_categories(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text,sort_order int not null default 0,created_at timestamptz not null default now());
create table public.menu_items(id uuid primary key default gen_random_uuid(),category_id uuid not null references public.menu_categories(id),name text not null,description text,price numeric(10,2) not null check(price>=0),image_url text,calories int,is_available boolean not null default true,is_spicy boolean not null default false,is_vegetarian boolean not null default false,sort_order int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(),order_number text not null unique default ('AB-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),user_id uuid not null references auth.users(id),status text not null default 'pending',order_type text not null default 'delivery',contact_name text,contact_phone text not null,address text,notes text,scheduled_for timestamptz,subtotal numeric(10,2) not null default 0,delivery_fee numeric(10,2) not null default 0,total numeric(10,2) not null default 0,cancel_reason text,decline_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,menu_item_id uuid references public.menu_items(id) on delete set null,item_name text not null,quantity int not null check(quantity>0),unit_price numeric(10,2) not null,created_at timestamptz not null default now());
create table public.order_events(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,status text not null,note text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.wishlist_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,menu_item_id uuid not null references public.menu_items(id) on delete cascade,created_at timestamptz not null default now(),unique(user_id,menu_item_id));
create table public.support_threads(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,order_id uuid references public.orders(id),subject text not null default 'Support request',status text not null default 'open',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.support_messages(id uuid primary key default gen_random_uuid(),thread_id uuid not null references public.support_threads(id) on delete cascade,sender_id uuid references auth.users(id),is_staff boolean not null default false,body text not null,created_at timestamptz not null default now());
create table public.delivery_partners(id uuid primary key references auth.users(id) on delete cascade,display_name text not null,phone text,vehicle_type text,vehicle_registration text,is_available boolean not null default false,is_verified boolean not null default false,rating numeric(3,2) not null default 5 check(rating between 0 and 5),total_deliveries int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.delivery_assignments(id uuid primary key default gen_random_uuid(),order_id uuid not null unique references public.orders(id) on delete cascade,partner_id uuid not null references public.delivery_partners(id),status text not null default 'assigned',assigned_at timestamptz not null default now(),picked_up_at timestamptz,delivered_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.delivery_locations(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.delivery_assignments(id) on delete cascade,partner_id uuid not null references public.delivery_partners(id) on delete cascade,latitude double precision not null check(latitude between -90 and 90),longitude double precision not null check(longitude between -180 and 180),accuracy_m double precision,heading double precision,speed_mps double precision,recorded_at timestamptz not null default now());
create index delivery_locations_assignment_recorded_idx on public.delivery_locations(assignment_id,recorded_at desc);
create index orders_user_created_idx on public.orders(user_id,created_at desc);
create index orders_status_created_idx on public.orders(status,created_at desc);
create or replace function public.has_role(_user_id uuid,_role public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role=_role); $$;
create or replace function public.is_staff(_user_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.has_role(_user_id,'staff') or public.has_role(_user_id,'admin'); $$;
create or replace function public.generate_order_number() returns text language sql as $$ select 'AB-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8)); $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,full_name) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do nothing; insert into public.user_roles(user_id,role) values(new.id,'customer') on conflict do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.user_roles enable row level security; alter table public.menu_categories enable row level security; alter table public.menu_items enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.order_events enable row level security; alter table public.wishlist_items enable row level security; alter table public.support_threads enable row level security; alter table public.support_messages enable row level security; alter table public.delivery_partners enable row level security; alter table public.delivery_assignments enable row level security; alter table public.delivery_locations enable row level security;
create policy profiles_self on public.profiles for select using(id=auth.uid() or public.is_staff(auth.uid()));
create policy profiles_update_self on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy roles_self on public.user_roles for select using(user_id=auth.uid() or public.is_staff(auth.uid()));
create policy menu_categories_read on public.menu_categories for select using(true);
create policy menu_items_read on public.menu_items for select using(true);
create policy orders_access on public.orders for select using(user_id=auth.uid() or public.is_staff(auth.uid()));
create policy orders_insert on public.orders for insert with check(user_id=auth.uid());
create policy orders_update on public.orders for update using(user_id=auth.uid() or public.is_staff(auth.uid())) with check(user_id=auth.uid() or public.is_staff(auth.uid()));
create policy order_items_access on public.order_items for select using(exists(select 1 from public.orders o where o.id=order_id and(o.user_id=auth.uid() or public.is_staff(auth.uid()))));
create policy order_items_insert on public.order_items for insert with check(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));
create policy order_events_access on public.order_events for select using(exists(select 1 from public.orders o where o.id=order_id and(o.user_id=auth.uid() or public.is_staff(auth.uid()))));
create policy order_events_insert on public.order_events for insert with check(public.is_staff(auth.uid()) or exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));
create policy wishlist_owner on public.wishlist_items for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy support_threads_access on public.support_threads for select using(user_id=auth.uid() or public.is_staff(auth.uid()));
create policy support_threads_insert on public.support_threads for insert with check(user_id=auth.uid());
create policy support_messages_access on public.support_messages for select using(exists(select 1 from public.support_threads t where t.id=thread_id and(t.user_id=auth.uid() or public.is_staff(auth.uid()))));
create policy support_messages_insert on public.support_messages for insert with check(sender_id=auth.uid() and exists(select 1 from public.support_threads t where t.id=thread_id and(t.user_id=auth.uid() or public.is_staff(auth.uid()))));
create policy delivery_partner_self on public.delivery_partners for select using(id=auth.uid() or public.is_staff(auth.uid()));
create policy delivery_partner_update on public.delivery_partners for update using(id=auth.uid()) with check(id=auth.uid());
create policy delivery_assignments_access on public.delivery_assignments for select using(partner_id=auth.uid() or public.is_staff(auth.uid()));
create policy delivery_assignments_staff on public.delivery_assignments for all using(public.is_staff(auth.uid())) with check(public.is_staff(auth.uid()));
create policy delivery_locations_access on public.delivery_locations for select using(partner_id=auth.uid() or public.is_staff(auth.uid()) or exists(select 1 from public.delivery_assignments da join public.orders o on o.id=da.order_id where da.id=assignment_id and o.user_id=auth.uid()));
create policy delivery_locations_insert on public.delivery_locations for insert with check(partner_id=auth.uid());
